import {request,surfaceContext} from './transport.mjs';
import {verificationFor,verificationSummary} from './verification.mjs';
const githubContext=surfaceContext();
const $=(s,root=document)=>root.querySelector(s),$$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const short=sha=>sha?.slice(0,7)||'—';
const badge=(label,kind='')=>`<span class="badge ${kind}">${esc(label)}</span>`;
const state={boot:null,doc:null,selected:null,mode:'world',level:'verify',inspector:'overview',lens:'change',search:'',file:null,fileMode:'diff',sourceCache:new Map(),modal:null,stack:[],reviewDraft:null,jobs:[],busy:false};
let toastTimer,saveTimer,pendingPatch={},mutationQueue=Promise.resolve(),lastNodeClick={id:null,at:0};
const component=()=>state.doc?.components.find(c=>c.id===state.selected);
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,6000);}
async function api(path,body){return request(path,body,state.boot?.token);}
async function bootstrap(){state.boot=await api('/api/bootstrap');state.jobs=state.boot.jobs||[];}
function setDoc(doc){state.doc=doc;if(!doc.components.some(c=>c.id===state.selected))state.selected=doc.components.find(c=>c.changedFiles.length)?.id||doc.components[0]?.id;}
async function openReview(id){await flushReviewSave();setDoc(await api('/api/reviews/'+id));state.mode='world';state.inspector='overview';state.file=null;state.reviewDraft=null;history.replaceState(null,'','#review='+id);render();}
async function action(body,{redraw=true}={}){const result=await api(`/api/reviews/${state.doc.id}/actions`,{expectedVersion:state.doc.version,...body});if(result.schema===1&&result.snapshot){setDoc(result);if(redraw)render();}return result;}
function patchReview(patch,{redraw=false}={}){mutationQueue=mutationQueue.catch(()=>{}).then(async()=>{let doc;try{doc=await action({action:'review',patch},{redraw});}catch(error){if(error.status!==409)throw error;setDoc(await api('/api/reviews/'+state.doc.id));doc=await action({action:'review',patch},{redraw});}if(state.reviewDraft)state.reviewDraft={...doc.review,...state.reviewDraft};updateReviewGate();return doc;});return mutationQueue;}
function scheduleReviewSave(patch){Object.assign(pendingPatch,patch);clearTimeout(saveTimer);const label=$('#review-save-state');if(label)label.textContent='Saving…';saveTimer=setTimeout(()=>flushReviewSave().catch(report),400);}
async function flushReviewSave(){clearTimeout(saveTimer);const patch=pendingPatch;pendingPatch={};if(Object.keys(patch).length)await patchReview(patch);await mutationQueue.catch(()=>{});}
function report(error){toast(error.message||String(error));}
function selectComponent(id,enter=false){state.selected=id;state.mode=enter?'component':'world';state.level='verify';state.inspector='overview';state.file=null;render();}
function titleForReview(doc){return doc.intent||`${doc.snapshot.head.ref} changes`;}

function shell(main,inspector=''){
 const doc=state.doc,reviewRows=state.boot.reviews.slice(0,5),repo=doc?.repository;
 $('#app').innerHTML=`<div class="studio"><aside class="sidebar"><a class="brand" href="#" data-action="home"><span class="brandmark">d.</span><span>docviz<span class="brand-sub">YOUR REVIEW WORKSPACE</span></span></a><button type="button" class="repo" data-action="open-project"><span class="repo-dot"></span><strong>${esc(repo?.name||'Your projects')}</strong><span class="pill">local</span><small>${esc(repo?.path||'Open a Git repository or PR')}</small></button>${doc?`<div class="eyebrow">WORKING CHANGE</div><button type="button" class="change-card" data-action="snapshot"><span class="tiny-label">${esc(doc.pr?'PR #'+doc.pr.number:'BRANCH COMPARISON')}</span><strong>${esc(titleForReview(doc))}</strong><span class="change-meta">${doc.snapshot.files.length} changed files · ${doc.properties.length} properties</span></button><nav aria-label="Review workflow"><button type="button" data-action="world" class="${state.mode==='world'?'active':''}"><span class="nav-num">01</span> Explore the change</button><button type="button" data-action="properties"><span class="nav-num">02</span> Inspect properties <span class="nav-end">${doc.properties.length}</span></button><button type="button" data-action="agents"><span class="nav-num">03</span> Agents & findings <span class="nav-end">${doc.findings.length}</span></button><button type="button" data-action="review"><span class="nav-num">04</span> Review & record <span class="nav-end">${doc.receiptCurrent?'✓':'○'}</span></button></nav>`:`<div><div class="eyebrow">PROJECTS</div>${state.boot.repositories.map(r=>`<button type="button" class="sidebar-project" data-action="open-project" data-repo="${r.id}">${esc(r.name)} ↗</button>`).join('')}</div>`}<div class="recent-section"><div class="eyebrow">RECENT REVIEWS</div>${reviewRows.map(r=>`<button type="button" class="recent-row" data-action="open-review" data-id="${r.id}">${esc(r.repository)}<small>${esc(r.head)} · ${short(r.commit)}</small></button>`).join('')||'<p class="source-note">Your saved reviews will appear here.</p>'}</div><div class="sidebar-bottom"><span class="status-dot"></span> Saved on this computer<small>Source is read from Git snapshots.<br>Project checks run only when requested.</small><button type="button" class="text-button" data-action="about">About this review tool ↗</button></div></aside><div class="workspace"><header class="topbar"><div class="crumb"><button type="button" class="text-button" data-action="home">Your reviews</button>${doc?`<span>/</span><strong>${esc(repo.name)}</strong>`:''}</div><div class="top-actions"><button type="button" class="button quiet" data-action="open-project">Open project / PR</button>${doc?`<button type="button" class="button agent-shortcut" data-action="agents">Agents & evidence</button><button type="button" class="button primary" data-action="review">${doc.receiptCurrent?'Review receipt':'Review change'} ↗</button>`:''}</div></header><main class="${doc?'':'home-main'}">${main}${inspector?`<aside class="inspector" aria-label="Component inspector">${inspector}</aside>`:''}</main><footer class="statusbar"><span><span class="status-dot"></span> ${doc?esc(doc.receiptCurrent?'Review recorded for this snapshot':doc.freshness.status==='current'?'Pinned Git snapshot · review in progress':'Selected refs moved · historical review'):'Local Git · durable reviews'}</span>${doc?`<span class="mono">${short(doc.snapshot.base.commit)} → ${short(doc.snapshot.head.commit)}</span><button type="button" class="text-button" data-action="refresh">Check for new commits ↻</button>`:'<span>No cloud account required for local source review.</span>'}</footer></div></div>`;
}
function renderHome(){document.body.classList.remove('verification-active');state.doc=null;shell(`<section><div class="home-intro"><div class="eyebrow">REVIEW BEFORE THE PR</div><h1>Your code, in context.</h1><p>Open a real change. Enter its components, inspect source and behavior, follow the evidence, and record your decision against the exact revision.</p><div class="home-actions"><button type="button" class="button primary" data-action="open-project">Open a project or PR ↗</button><button type="button" class="button" data-action="about">How this works</button></div></div><div class="home-section"><h2>Your projects</h2><p>Local checkouts work without GitHub authentication.</p></div><div class="project-grid">${state.boot.repositories.map(r=>`<button type="button" class="project-card" data-action="open-project" data-repo="${r.id}"><i class="project-icon" aria-hidden="true">${esc(r.name[0])}</i><span><strong>${esc(r.name)}</strong><small>${esc(r.path)}</small><small>${r.bare?'Cached repository · source and isolated checks':'Local checkout · source and requested checks'}</small></span></button>`).join('')}<button type="button" class="project-card" data-action="add-project"><i class="project-icon" aria-hidden="true">+</i><span><strong>Add another repository</strong><small>Paste its folder path or a GitHub PR URL.</small></span></button></div><div class="home-section"><h2>Resume a review</h2><p>Decisions and evidence persist when the app closes.</p></div><div class="history-list">${state.boot.reviews.map(r=>`<button type="button" class="history-row" data-action="open-review" data-id="${r.id}"><div><strong>${esc(r.intent||r.repository)}</strong><small>${esc(r.repository)} · ${esc(r.base)} → ${esc(r.head)} · ${r.changedFiles} changed files</small></div><span class="history-commit">${short(r.commit)}</span>${badge(r.hasReceipt?'Receipt saved':'In progress',r.hasReceipt?'':'neutral')}<span>↗</span></button>`).join('')||'<div class="empty-view">No reviews yet. Open a project to begin.</div>'}</div></section>`);}
function propertiesFor(c){return state.doc.properties.filter(p=>p.componentId===c.id);}
function evidenceFor(p){return state.doc.evidence.filter(e=>e.propertyIds?.includes(p.id));}
function propertyStatus(p){const evidence=evidenceFor(p).filter(e=>!e.outdatedPropertyIds?.includes(p.id)),observed=evidence.flatMap(e=>e.stale||e.outdatedPropertyIds?.includes(p.id)?[]:(e.observations||[]).filter(o=>o.propertyId===p.id));if(observed.some(o=>o.result==='fails'))return['Observed failure','bad'];if(observed.length&&observed.every(o=>o.result==='holds'))return['Observed assertions',''];if(evidence.some(e=>e.kind==='executed-command'&&e.result==='fail'))return['Related check failed','bad'];if(evidence.some(e=>e.kind==='executed-command'&&e.result==='pass'&&!e.stale))return['Command passed · property result unknown','pending'];if(evidence.some(e=>e.result==='contradicts'))return['Source contradiction','bad'];if(evidence.some(e=>e.kind==='source-judgment'))return['Source judgment','neutral'];if(evidence.some(e=>e.kind==='reported'))return['Reported evidence','pending'];return[p.sources.length?'Source linked · runtime unknown':'No evidence attached','pending'];}
function jobBanner(){const jobs=state.jobs.filter(j=>j.reviewId===state.doc?.id&&j.status==='running');return jobs.map(j=>`<div class="job-state"><span class="busy-dot"></span><strong>${esc(j.label)} is running.</strong> You can keep exploring this snapshot.<button type="button" class="text-button" data-action="agents"> Inspect progress ↗</button></div>`).join('');}
function render(){if(!state.boot)return;if(!state.doc){renderHome();return;}const d=state.doc,c=component();document.body.classList.toggle('verification-active',state.mode==='component'&&state.level==='verify');if(!c){renderHome();return;}
 const main=`<section class="world-column">${state.mode==='component'?'<button type="button" class="back-world text-button" data-action="world">← Repository world</button>':''}<div class="world-heading"><div><div class="eyebrow">${state.mode==='component'?'RESPONSIBILITY → BEHAVIOR → PROPERTIES → IMPLEMENTATION':'REAL REPOSITORY · PINNED CHANGESET'}</div><h1>${esc(state.mode==='component'?c.title:d.repository.name+' · change world')}</h1><p>${esc(state.mode==='component'?(state.level==='verify'?`${c.changedFiles.length} changed files · ${propertiesFor(c).length} property definitions · Select a property to trace its support.`:c.responsibility||'A source grouping awaiting a confirmed responsibility.'):titleForReview(d))}</p></div><button type="button" class="button" data-action="${state.mode==='component'?'describe-component':'snapshot'}">${state.mode==='component'?'Describe responsibility':'Inspect comparison'} ↗</button></div>${state.mode==='world'?verificationOverview():''}${jobBanner()}${d.freshness.status!=='current'?`<div class="live-review-banner"><div><strong>The selected refs have moved.</strong><p>This review still describes ${short(d.snapshot.head.commit)}. Its receipt cannot approve the newer candidate.</p></div><button type="button" class="button" data-action="refresh">Open current change →</button></div>`:''}${state.mode==='world'?`<div class="world-toolbar"><div class="segmented" role="group" aria-label="Map focus"><button type="button" data-action="lens" data-lens="change" class="${state.lens==='change'?'selected':''}">Changed components</button><button type="button" data-action="lens" data-lens="all" class="${state.lens==='all'?'selected':''}">All components</button></div><label class="search"><span aria-hidden="true">⌕</span><input id="component-search" type="search" aria-label="Find a component" placeholder="Find a component…" value="${esc(state.search)}"></label></div><div class="world-frame live-graph"><div class="world-viewport" id="world-viewport"><div id="world-map" class="world-map" role="group" aria-label="Repository component graph"><svg class="connections" role="img" aria-label="Source and review-model relationships"><defs><marker id="edge-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M1 1L8 5 1 9" fill="none" stroke="currentColor"/></marker></defs><g id="graph-edges"></g></svg><div id="graph-nodes"></div></div></div><div class="world-footer"><span id="graph-caption"></span><span>Orange rim: changed · violet link: source interpretation</span></div></div><div class="view-callout"><strong>${d.properties.length?'Responsibilities and properties retain their stated provenance.':'Start with source. Add meaning as you review.'}</strong><p>${d.properties.length?'Agent-proposed contracts need your confirmation. Source links and explanations remain distinct from execution evidence.':'Directory-derived bubbles are provisional groupings. Add a property yourself or ask your agent to draft a component model; none is invented automatically.'}</p><div class="inline-actions"><button type="button" class="button" data-action="agents">Draft with my agent →</button><button type="button" class="text-button" data-action="add-property">Add a property manually ↗</button></div></div>`:renderComponent(c)}<div class="component-decision"><div><strong>${esc(c.title)}</strong><div class="source-note">${c.changedFiles.length} changed files in this responsibility</div></div><label>My component review<select data-component-decision="${c.id}" aria-label="Review component ${esc(c.title)}">${decisionOptions(d.review.componentDecisions[c.id])}</select></label></div></section>`;
 shell(main,renderInspector(c));if(state.mode==='world')drawGraph();if(state.mode==='component'&&state.level==='implementation')loadMainSource();
}
function decisionOptions(value='',blank='Not reviewed'){return `<option value="" ${!value?'selected':''}>${blank}</option><option value="satisfied" ${value==='satisfied'?'selected':''}>Satisfied within reviewed scope</option><option value="follow-up" ${value==='follow-up'?'selected':''}>Retain as follow-up</option><option value="changes" ${value==='changes'?'selected':''}>Needs changes</option>`;}
function drawGraph(){const host=$('#world-map');if(!host)return;const d=state.doc,search=state.search.trim().toLowerCase();let nodes=d.components.filter(c=>(state.lens==='all'||c.changedFiles.length||c.id===state.selected)&&(!search||`${c.title} ${c.responsibility} ${c.files.join(' ')}`.toLowerCase().includes(search)));const total=nodes.length;nodes=nodes.slice(0,20);const w=Math.max(280,Math.round(host.getBoundingClientRect().width)),cols=w<440?2:w<700?3:4,rows=Math.ceil(nodes.length/cols),height=Math.max(260,rows*160+70),positions=new Map();host.style.height=height+'px';$('.connections').setAttribute('viewBox',`0 0 ${w} ${height}`);
 const colors=['#d9e7cc','#d9d7ed','#e8dcc5','#d2e6df','#e5d5e8'];
 $('#graph-nodes').innerHTML=nodes.map((c,i)=>{const row=Math.floor(i/cols),inRow=Math.min(cols,nodes.length-row*cols),x=w/(inRow+1)*(i%cols+1),y=85+row*160;positions.set(c.id,[x,y]);const size=c.id===state.selected?110:100;return `<button type="button" class="node ${c.id===state.selected?'selected':''} ${c.changedFiles.length?'changed':''}" style="left:${x}px;top:${y}px;width:${size}px;height:${size}px;--bubble:${colors[i%colors.length]}" data-action="select-component" data-component="${c.id}" aria-label="Select ${esc(c.title)}" aria-pressed="${c.id===state.selected}"><span class="node-symbol" aria-hidden="true">${esc(c.title[0])}</span><strong title="${esc(c.title)}">${esc(c.title.length>31?c.title.slice(0,29)+'…':c.title)}</strong><small>${c.changedFiles.length} changed / ${c.files.length} files</small><span class="bubble-signal">${propertiesFor(c).length} properties · ${d.findings.filter(f=>f.componentId===c.id).length} findings</span></button>`;}).join('');
 $('#graph-edges').innerHTML=d.relationships.filter(l=>positions.has(l.from)&&positions.has(l.to)).map((l,i)=>{const[x,y]=positions.get(l.from),[tx,ty]=positions.get(l.to),dx=tx-x,dy=ty-y,n=Math.hypot(dx,dy),sx=x+dx/n*60,sy=y+dy/n*60,ex=tx-dx/n*60,ey=ty-dy/n*60;return `<path class="edge ${l.basis==='agent-source-interpretation'?'semantic':''} ${l.from===state.selected||l.to===state.selected?'active':''}" d="M${sx} ${sy} Q${(sx+ex)/2+15} ${(sy+ey)/2-15} ${ex} ${ey}" marker-end="url(#edge-arrow)" data-action="relationship" data-id="${d.relationships.indexOf(l)}"><title>${esc(l.kind)} · inspect why connected</title></path>`;}).join('');
 $('#graph-caption').textContent=nodes.length?`${nodes.length} of ${total} matching components · ${d.relationships.length} source-grounded links`:'No components match this search.';
}
function renderComponent(c){const d=state.doc,props=propertiesFor(c);let body='';if(state.level==='verify')body=renderVerification(c);
 if(state.level==='abstract')body=`<div class="component-abstract"><div class="big-component-bubble" style="--bubble:#dce7d1"><span aria-hidden="true">${esc(c.title[0])}</span><strong>${esc(c.title)}</strong></div><div><span class="eyebrow">${esc(c.basis)}</span><h2>${esc(c.responsibility||'What responsibility does this part of your system own?')}</h2><p>${c.responsibility?'This description is part of the review model, with its authority shown above.':'The current boundary comes from file structure. You or your agent can name the meaningful responsibility and its inputs and outputs.'}</p>${c.inputs.length||c.outputs.length?`<div class="ports"><div><span>INPUTS</span>${c.inputs.map(esc).join('<br>')||'Not specified'}</div><div><span>OUTPUTS</span>${c.outputs.map(esc).join('<br>')||'Not specified'}</div></div>`:''}<div class="inline-actions"><button type="button" class="button primary" data-action="level" data-level="concrete">Explore behavior →</button><button type="button" class="text-button" data-action="describe-component">Edit responsibility ↗</button></div></div></div>`;
 if(state.level==='concrete')body=c.behavior.length?`<div class="component-intro"><span class="eyebrow">SOURCE-GROUNDED EXPLANATION</span><h2>How this component changes</h2><p>These steps explain the linked source. They are not observed execution traces.</p></div>${c.behavior.map((b,i)=>`<div class="property-card"><div class="property-title"><strong>${i+1}. ${esc(b.label)}</strong>${badge('Explanatory','neutral')}</div><div class="compare-row"><span>Before</span><p>${esc(b.before||'Not specified')}</p></div><div class="compare-row"><span>After</span><p>${esc(b.after||'Not specified')}</p></div>${anchors(b.sources)}</div>`).join('')}`:`<div class="component-empty"><h3>No behavior model has been supplied.</h3><p>You can inspect the actual diff now, add a property, or ask your agent to describe the behavior. The app will keep that proposal separate from test evidence.</p><button type="button" class="button" data-action="level" data-level="implementation">Inspect source & diff →</button><button type="button" class="button" data-action="agents">Draft with my agent →</button></div>`;
 if(state.level==='properties')body=`<div class="component-intro"><span class="eyebrow">CONDITIONS · EXPECTATIONS · VIOLATIONS</span><h2>${props.length?props.length+' properties in this component':'No property specified yet'}</h2><p>A property defines what should hold. Its evidence and your review decision are recorded separately.</p></div>${props.map(p=>{const[label,kind]=propertyStatus(p);return `<article class="property-card"><div class="property-authority">${p.authority==='human-confirmed'?'Human-confirmed definition':'Agent proposal · not yet confirmed'}</div><div class="property-title"><button type="button" data-action="property" data-property="${p.id}">${esc(p.title)} ↗</button>${badge(label,kind)}</div><div class="property-condition"><span>WHEN</span>${esc(p.condition)}</div><p>${esc(p.expectation)}</p><div class="property-tools"><button type="button" class="text-button" data-action="property" data-property="${p.id}">Inspect behavior, evidence & findings →</button></div></article>`;}).join('')}<button type="button" class="button" data-action="add-property">Add a property ↗</button>`;
 if(state.level==='implementation'){const selected=state.file||c.changedFiles[0]||c.files[0];state.file=selected;body=`<div class="component-intro"><span class="eyebrow">IMMUTABLE GIT SOURCE</span><h2>Read the actual implementation.</h2><p>Diff and source are read from the pinned commits, not your working tree. Listed files remain inspectable even when import extraction is limited.</p></div><div class="source-tools"><select id="source-file" aria-label="Component source file">${c.files.map(p=>`<option value="${esc(p)}" ${p===selected?'selected':''}>${esc(p)}</option>`).join('')}</select><div class="segmented" role="group" aria-label="Source revision">${[['diff','Diff'],['head','Candidate'],['base','Base']].map(([mode,label])=>`<button type="button" class="${state.fileMode===mode?'selected':''}" data-action="source-mode" data-mode="${mode}">${label}</button>`).join('')}</div></div><div id="main-source" class="source-note">Loading pinned source…</div>`;}
 return `<section id="component-view"><div class="component-nav" role="group" aria-label="Component design level">${['verify','abstract','concrete','properties','implementation'].map((level,i)=>`<button type="button" class="${state.level===level?'active':''}" data-action="level" data-level="${level}" aria-pressed="${state.level===level}"><span>0${i+1}</span>${level[0].toUpperCase()+level.slice(1)}</button>`).join('')}</div><div class="component-content">${body}</div></section>`;
}
function anchors(refs){return refs?.length?refs.map((r,i)=>`<button type="button" class="source-link" data-action="anchor" data-path="${esc(r.path)}" data-side="${r.side}" data-from="${r.from}" data-to="${r.to}">${esc(r.path)}:${r.from}–${r.to}<small>${r.side==='head'?'Candidate':'Base'} ${short(state.doc.snapshot[r.side].commit)} · inspect exact lines ↗</small></button>`).join(''):'<p class="source-note">No source reference supplied.</p>';}
function renderInspector(c){const d=state.doc,props=propertiesFor(c);return `<div class="inspector-title"><span class="eyebrow">INSIDE THE BUBBLE</span>${badge(c.changedFiles.length?'Changed':'Context',c.changedFiles.length?'':'neutral')}</div><div id="inspector-heading"><h2>${esc(c.title)}</h2><p>${esc(c.basis)}</p></div><div class="inspector-tabs" role="tablist" aria-label="Component inspector"><button type="button" class="${state.inspector==='overview'?'active':''}" data-action="inspector" data-tab="overview" role="tab" aria-selected="${state.inspector==='overview'}">Overview</button><button type="button" class="${state.inspector==='evidence'?'active':''}" data-action="inspector" data-tab="evidence" role="tab" aria-selected="${state.inspector==='evidence'}">Evidence</button><button type="button" class="${state.inspector==='findings'?'active':''}" data-action="inspector" data-tab="findings" role="tab" aria-selected="${state.inspector==='findings'}">Findings</button></div>${state.inspector==='overview'?`<p>${esc(c.responsibility||'This grouping follows the source directory. Its domain responsibility has not been confirmed.')}</p><button type="button" class="button primary section-link" data-action="enter">Verify component →</button><h3>CHANGED FILES</h3>${fileRows(c.changedFiles)}<h3>LINKED COMPONENTS</h3>${d.relationships.filter(l=>l.from===c.id||l.to===c.id).slice(0,10).map(l=>{const other=d.components.find(x=>x.id===(l.from===c.id?l.to:l.from));return other?`<button type="button" class="relation-row" data-action="relationship" data-id="${d.relationships.indexOf(l)}">${esc(other.title)}<span>${esc(l.kind)} ↗</span></button>`:'';}).join('')||'<p class="source-note">No cross-component import detected. Runtime protocols and aliases may be outside this scan.</p>'}<p class="source-note">Imports and proposed semantic links retain source anchors. Open a connection to inspect its reason; neither proves runtime behavior.</p>`:state.inspector==='evidence'?`<h3>PROPERTY EVIDENCE</h3>${props.map(p=>{const[label,kind]=propertyStatus(p);return `<button type="button" class="evidence-row" data-action="property" data-property="${p.id}"><strong>${esc(p.title)}</strong>${badge(label,kind)}</button>`;}).join('')||'<p class="source-note">No behavioral property is specified. Source review is available now.</p>'}<h3>RECORDED CHECKS & REPORTS</h3>${d.evidence.map(e=>`<button type="button" class="evidence-row" data-action="evidence" data-id="${e.id}"><strong>${esc(e.kind)}</strong><small>${esc(e.scope)}</small>${badge(e.result,e.result==='fail'||e.result==='contradicts'?'bad':'neutral')}</button>`).join('')||'<p class="source-note">No execution or reported evidence has been added.</p>'}<div class="inline-actions"><button type="button" class="button" data-action="run-check">Run a check ↗</button><button type="button" class="text-button" data-action="agents">Agent contributions ↗</button></div>`:`${renderFindingCards(d.findings.filter(f=>f.componentId===c.id||props.some(p=>p.id===f.propertyId)))}<button type="button" class="button section-link" data-action="agents">All agent contributions →</button>`}`;}
function fileRows(paths){return paths.length?paths.map(path=>{const f=state.doc.snapshot.files.find(f=>f.path===path);return `<button type="button" class="file-row" data-action="file" data-path="${esc(path)}"><span class="file-status">${esc(f?.status||'·')}</span><code>${esc(path)}</code><span>↗</span></button>`;}).join(''):'<p class="source-note">No direct edits in this component.</p>';}
function renderFindingCards(findings){return findings.map(f=>`<article class="finding-row">${badge(f.actor?.name||'Agent','neutral')}${badge(f.severity,f.severity==='blocking'?'bad':'pending')}<h3>${esc(f.claim)}</h3><p>${esc(f.scope)}</p><button type="button" class="button small" data-action="finding" data-id="${f.id}">${state.doc.review.findingResolutions[f.id]?'Inspect resolution':'Inspect & resolve'} ↗</button></article>`).join('')||'<p class="source-note">No agent finding is recorded for this scope.</p>';}
async function loadMainSource(){const id=state.doc.id,path=state.file,mode=state.fileMode,key=id+mode+path;try{let value=state.sourceCache.get(key);if(!value){value=await api(`/api/reviews/${id}/${mode==='diff'?'diff':'source'}?path=${encodeURIComponent(path)}${mode==='diff'?'':'&side='+mode}`);state.sourceCache.set(key,value);}if(state.doc.id===id&&state.file===path&&state.fileMode===mode&&$('#main-source'))$('#main-source').outerHTML=`<div id="main-source">${sourceHTML(value,mode)}</div>`;}catch(error){if($('#main-source'))$('#main-source').innerHTML=`<div class="component-empty"><h3>Source is not rendered here.</h3><p>${esc(error.message)}</p><p>The file remains part of the change. Try the other revision for removed or added files.</p></div>`;}}
function sourceHTML(value,mode,focus=null){const githubLink=sourceOnGitHub(value,mode,focus);const lines=value.text.split('\n');return `<div class="source-note">${esc(value.path)} · ${mode==='diff'?'pinned comparison':`${mode==='head'?'candidate':'base'} ${short(value.commit)} · blob ${short(value.blob)}`}${value.truncated?' · diff truncated at viewer limit':''}${githubLink?` · <a href="${esc(githubLink)}" target="_blank" rel="noopener">Open on GitHub ↗</a>`:''}</div><pre class="source-view">${lines.map((line,i)=>`<span class="source-line ${mode==='diff'?(line.startsWith('+')?'added-line':line.startsWith('-')?'removed-line':line.startsWith('@@')?'hunk-line':''):focus&&i+1>=focus.from&&i+1<=focus.to?'focus-line':''}">${mode==='diff'?'':`<span class="line-number">${i+1}</span>`}${esc(line)}</span>`).join('')}</pre>`;}

function modal(kind,data={},push=false){if(push&&state.modal)state.stack.push(state.modal);else if(!push)state.stack=[];state.modal={kind,data};renderModal();if(!$('#dialog').open)$('#dialog').showModal();}
async function backModal(){await flushReviewSave();const previous=state.stack.pop();if(previous){state.modal=previous;renderModal();}else closeModal();}
function closeModal(){flushReviewSave().catch(report);$('#dialog').close();state.modal=null;state.stack=[];render();}
function modalFrame(title,label,body){$('#dialog-title').textContent=title;$('#dialog-label').textContent=label;$('#dialog-content').innerHTML=`${state.stack.length?'<div class="modal-back"><button type="button" class="text-button" data-action="back-modal">← Back to review</button><span class="view-label">PINNED SNAPSHOT</span></div>':''}${body}`;$('#dialog').scrollTop=0;}
function field(label,name,value='',type='text',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function textarea(label,name,value='',extra=''){return `<label class="field">${label}<textarea name="${name}" ${extra}>${esc(value)}</textarea></label>`;}
function renderModal(){const m=state.modal,d=state.doc;if(!m)return;
 if(m.kind==='project'){const r=m.data.refs,repo=state.boot.repositories.find(r=>r.id===m.data.repositoryId);modalFrame('Open a real change.','YOUR PROJECTS',`<div class="dialog-tabs"><button type="button" class="${m.data.tab!=='pr'?'active':''}" data-action="project-tab" data-tab="local">Local repository</button><button type="button" class="${m.data.tab==='pr'?'active':''}" data-action="project-tab" data-tab="pr">GitHub PR</button></div>${m.data.tab==='pr'?`<form id="open-pr-form">${field('GitHub pull request URL','url','','url','required placeholder="https://github.com/owner/repo/pull/123"')}<p class="dialog-copy">Public PRs are cached locally. For private projects, open your local checkout. GitHub publication happens outside this app.</p><div class="form-actions"><button class="button primary">Load PR →</button></div></form>`:`<label class="field">Repository<select id="project-select"><option value="">Choose a repository…</option>${state.boot.repositories.map(p=>`<option value="${p.id}" ${p.id===m.data.repositoryId?'selected':''}>${esc(p.name)} · ${esc(p.path)}</option>`).join('')}</select></label><form id="add-repository-form"><label class="field">Add a repository folder<input name="path" placeholder="/Users/you/projects/my-project" required autocomplete="off"></label><button class="button small">Add folder</button></form>${repo?`<form id="open-comparison-form"><p class="dialog-copy">${esc(repo.path)}${repo.bare?' · cached Git source · isolated verification available':''}</p>${r?`<datalist id="git-refs">${r.refs.map(ref=>`<option value="${esc(typeof ref==='string'?ref:ref.name)}"></option>`).join('')}</datalist><div class="form-row">${field('Target / base ref','baseRef',m.data.baseRef||r.defaultBase||'main','text','required list="git-refs"')}${field('Candidate ref','headRef',m.data.headRef||r.active||'HEAD','text','required list="git-refs"')}</div><label class="field">Comparison<select name="mode"><option value="merge-base">Changes since the common ancestor (PR style)</option><option value="direct">Direct base → candidate</option></select><small>Only committed revisions are reviewed. Your working files remain untouched.</small></label><div class="form-actions"><button class="button primary">Enter the change world →</button></div>`:'<p class="dialog-copy">Reading Git refs…</p>'}</form>`:''}`}`);return;}
 if(m.kind==='about'){modalFrame('Your review, before the PR.','HOW TO USE DOCVIZ',`<ol class="review-limitations"><li>Open a local branch comparison or a public GitHub PR.</li><li>Enter a component to read its responsibility, behavior, properties and actual source diff.</li><li>Add a property yourself, or request an agent proposal. Inspect and confirm its definition.</li><li>Run a check in the matching checkout. Inspect agent findings and record why you accept, defer or reject each one.</li><li>Record your review. Export a revision-bound receipt and PR handoff; run integration CI separately.</li></ol><p class="dialog-copy">Directory bubbles and detected imports are a starting map. Source explanations, model judgments, imported reports and executed assertions have separate labels. Reviews and job results are stored on this computer in the app’s data folder.</p><div class="form-actions"><button type="button" class="button primary" data-action="close-dialog">Got it</button></div>`);return;}
 if(m.kind==='snapshot'){modalFrame('What exactly am I reviewing?','PINNED GIT COMPARISON',`<p class="dialog-copy">${esc(d.repository.path)}<br>${esc(d.intent)}</p><div class="snapshot-ids"><div>BASE · ${esc(d.snapshot.base.ref)}<code>${d.snapshot.base.commit}</code><small>Requested target: ${d.snapshot.base.requestedCommit}</small></div><div>CANDIDATE · ${esc(d.snapshot.head.ref)}<code>${d.snapshot.head.commit}</code></div></div><p class="dialog-copy">${d.snapshot.mode==='merge-base'?'PR-style changes since the common ancestor.':'Direct comparison between the two selected commits.'} Ref status: ${esc(d.freshness.status)}. A receipt binds both commits and the reviewed model.</p><h3>Changed files</h3>${fileRows(d.snapshot.files.map(f=>f.path))}<h3>Map coverage</h3><p class="dialog-copy">${d.snapshot.coverage.indexed} / ${d.snapshot.coverage.sourceFiles} code files scanned for supported relative imports. Paths, aliases and runtime protocols outside this syntax are not resolved. Edges indicate possible relevance.</p><details><summary>Import-scan omissions (${d.snapshot.coverage.omissions.length})</summary><ul class="review-limitations">${d.snapshot.coverage.omissions.map(x=>`<li>${esc(x.path)} — ${esc(x.reason)}</li>`).join('')}</ul></details>`);return;}
 if(m.kind==='source'){modalFrame(m.data.path,'IMMUTABLE SOURCE',`<div class="source-tools">${['diff','head','base'].map(side=>`<button type="button" class="button small ${m.data.side===side?'primary':''}" data-action="modal-source-mode" data-side="${side}">${side==='head'?'Candidate':side==='base'?'Base':'Diff'}</button>`).join('')}</div><div id="modal-source">Loading pinned source…</div>`);loadModalSource();return;}
 if(m.kind==='relationship'){const l=d.relationships[Number(m.data.id)],a=d.components.find(c=>c.id===l.from),b=d.components.find(c=>c.id===l.to);modalFrame(a.title+' → '+b.title,'WHY THESE COMPONENTS CONNECT',`${badge(l.kind,'neutral')}<p class="dialog-copy">${esc(l.reason||'A supported relative import in the source connects files owned by these components. This is possible relevance, not an observed execution path.')}</p><p class="source-note">Basis: ${esc(l.basis)}${l.actor?' · '+esc(l.actor.name):''}</p>${anchors(l.sources)}<div class="inline-actions"><button type="button" class="button" data-action="visit-connected" data-component="${a.id}">Enter ${esc(a.title)} ↗</button><button type="button" class="button" data-action="visit-connected" data-component="${b.id}">Enter ${esc(b.title)} ↗</button></div>`);return;}
 if(m.kind==='component'){const c=component();modalFrame('Name the responsibility.','HUMAN-DEFINED COMPONENT',`<form id="component-form">${field('Component name','title',c.title,'text','required maxlength="200"')}${textarea('Responsibility · what does it own?','responsibility',c.responsibility)}<p class="dialog-copy">Files and source-grounded behavior are retained. Agent packages can propose different component boundaries.</p><div class="form-actions"><button class="button primary">Save responsibility</button></div></form>`);return;}
 if(m.kind==='property-form'){const p=d.properties.find(x=>x.id===m.data.id);modalFrame(p?'Edit this property.':'Define what should hold.','HUMAN-CONFIRMED PROPERTY',`<form id="property-form"><label class="field">Owning component<select name="componentId">${d.components.map(c=>`<option value="${c.id}" ${(p?.componentId||state.selected)===c.id?'selected':''}>${esc(c.title)}</option>`).join('')}</select></label>${field('Property title','title',p?.title||'','text','required maxlength="250"')}${textarea('When · condition that activates this property','condition',p?.condition||'','required')}${textarea('Then · expected behavior','expectation',p?.expectation||'','required')}${textarea('Violation · what would show it is broken?','violation',p?.violation||'','required')}<label class="field">Source references (JSON array)<textarea name="sources" class="mono">${esc(JSON.stringify(p?.sources?.map(({side,path,from,to})=>({side,path,from,to}))||[],null,2))}</textarea><small>Optional: [{"side":"head","path":"src/file.js","from":1,"to":10}]. Exact line bounds are validated against Git.</small></label><div class="form-actions"><button class="button primary">Save property definition</button></div></form>`);return;}
 if(m.kind==='property'){const p=d.properties.find(x=>x.id===m.data.id);if(!p){closeModal();return;}const[label,kind]=propertyStatus(p),tab=m.data.tab||'behavior';modalFrame(p.title,'INSPECT A PROPERTY',`${badge(label,kind)} ${badge(p.authority==='human-confirmed'?'Definition confirmed':'Agent-proposed definition','neutral')}<div class="dialog-tabs"><button type="button" class="${tab==='behavior'?'active':''}" data-action="property-tab" data-tab="behavior">Behavior</button><button type="button" class="${tab==='evidence'?'active':''}" data-action="property-tab" data-tab="evidence">Evidence (${evidenceFor(p).length})</button><button type="button" class="${tab==='agents'?'active':''}" data-action="property-tab" data-tab="agents">Agent findings</button></div><p class="source-note">Property ID: <code>${esc(p.id)}</code> <button type="button" class="text-button" data-action="copy-property-id" data-property="${p.id}">Copy ID</button></p>${evidenceMap(p)}${tab==='behavior'?`<div class="property-contract"><h3>WHEN</h3><p>${esc(p.condition)}</p><h3>EXPECTED</h3><p>${esc(p.expectation)}</p><h3>VIOLATED IF</h3><p>${esc(p.violation)}</p></div>${anchors(p.sources)}${propertyBehavior(p)}<div class="inline-actions"><button type="button" class="button" data-action="edit-property" data-property="${p.id}">Edit definition ↗</button>${p.authority!=='human-confirmed'?`<button type="button" class="button" data-action="confirm-property" data-property="${p.id}">Confirm this definition</button>`:''}</div>`:tab==='evidence'?`${evidenceFor(p).map(e=>`<button type="button" class="evidence-row" data-action="evidence" data-id="${e.id}"><strong>${esc(e.kind)} · ${esc(e.result)}${e.outdatedPropertyIds?.includes(p.id)?' · earlier property definition':''}</strong><small>${esc(e.scope)}</small>${(e.observations||[]).filter(o=>o.propertyId===p.id).map(o=>`<small>${esc(o.assertion)} → ${esc(o.result)}</small>`).join('')}</button>`).join('')||'<div class="component-empty"><h3>No runtime assertion is recorded for this property.</h3><p>Read the exact source links, import a scoped report, or run an instrumented check. A command’s exit code alone does not establish this property.</p></div>'}<button type="button" class="button" data-action="run-check">Run a verification command ↗</button>`:renderFindingCards(d.findings.filter(f=>f.propertyId===p.id||f.componentId===p.componentId))}<div class="review-callout"><strong>Your decision on this property</strong><p>Decide within the evidence you inspected. A follow-up keeps the gap visible in your receipt.</p><label class="field">Review decision<select id="property-decision">${decisionOptions(m.data.decision??d.review.propertyDecisions[p.id])}</select></label></div><div class="form-actions spread"><button type="button" class="text-button" data-action="back-modal">← Back</button><button type="button" class="button primary" data-action="record-property" data-property="${p.id}">Record decision & return</button></div>`);return;}
 if(m.kind==='evidence'){const e=d.evidence.find(e=>e.id===m.data.id);modalFrame(e.kind,'EVIDENCE & PROVENANCE',`${badge(e.result,e.result==='fail'||e.result==='contradicts'?'bad':'neutral')}<p class="dialog-copy">${esc(e.scope)}</p><p class="source-note">${esc(e.actor?.name||'Imported')} · ${esc(e.recordedAt)} · snapshot ${short(e.snapshotId)}</p>${e.argv?`<p class="source-note">Execution folder: ${esc(e.executionPath||'matching project checkout')}</p><pre class="source-view">${esc(JSON.stringify(e.argv))}\nExit code: ${esc(e.exitCode)}${e.stale?' · checkout changed during execution':''}</pre>`:''}${e.observations?.length?`<h3>Property-specific records</h3>${e.observations.map(o=>`<div class="property-contract"><h3>${esc(o.propertyId)} · ${esc(o.result)}</h3><p>${esc(o.assertion)}</p></div>`).join('')}`:'<p class="source-note">No property-specific executed observation is contained in this evidence.</p>'}${e.notes?`<p class="dialog-copy">${esc(e.notes)}</p>`:''}${anchors(e.sources)}${e.supported!=null?`<p class="dialog-copy">Jev source support: ${esc(e.supported)} · contradiction: ${esc(e.contradicted)}. These are model judgments, not measured pass rates.</p>`:''}${e.output!=null?`<h3>Captured command output</h3><pre class="source-view">${esc(e.output)}</pre>${e.truncated?'<p class="source-note">Output truncated at 1 MB.</p>':''}`:''}`);return;}
 if(m.kind==='finding'){const f=d.findings.find(f=>f.id===m.data.id),r=d.review.findingResolutions[f.id]||{};modalFrame(f.claim,'AGENT FINDING · HUMAN DISPOSITION',`${badge(f.actor?.name||'Agent','neutral')} ${badge(f.severity,'pending')}<div class="property-contract"><h3>REASONING</h3><p>${esc(f.reasoning)}</p><h3>SCOPE</h3><p>${esc(f.scope)}</p><h3>WHAT WOULD RESOLVE THIS?</h3><p>${esc(f.resolvingCheck||'Inspect the cited source and record the reasoning for your disposition.')}</p></div>${anchors(f.sources)}<form id="finding-form"><label class="field">My disposition<select name="disposition">${[['resolved','Resolved by inspected evidence'],['follow-up','Keep as follow-up'],['dismissed','Disagree with this finding'],['changes','Changes required']].map(([v,t])=>`<option value="${v}" ${r.disposition===v?'selected':''}>${t}</option>`).join('')}</select></label>${textarea('Why · cite the evidence or explain the disagreement','rationale',r.rationale||'','required')}<div class="form-actions"><button class="button primary">Record disposition & return</button></div></form>`);return;}
 if(m.kind==='agents'){modalFrame('Agents contribute. You decide.','MODELS · EVIDENCE · DISAGREEMENTS',`<p class="dialog-copy">Draft a component model, then ask a separate reviewer or verifier to challenge it. Their claims and reasons stay visible. Nothing is applied automatically; no synthetic disagreements are added.</p><form id="agent-form"><div class="form-row"><label class="field">Role<select name="role"><option value="author">Author · draft component model & properties</option><option value="reviewer">Reviewer · challenge the model and change</option><option value="verifier">Verifier · identify evidence gaps</option></select></label><label class="field">Configured local agent<select name="provider"><option value="auto">Automatic</option>${Object.entries(state.boot.providers).filter(([,v])=>v).map(([k])=>`<option value="${k}">${k==='claude'?'Claude Code':'Codex CLI'}</option>`).join('')}</select><small>Uses your existing CLI login. Context is sent when you run it.</small></label></div><button class="button primary" ${!Object.values(state.boot.providers).some(Boolean)?'disabled':''}>Run agent analysis →</button></form><div id="agent-job-list">${renderJobs()}</div><h3>Contributions (${d.contributions.length})</h3>${d.contributions.map(c=>`<article class="agent-package">${badge(c.actor.role,'neutral')} ${badge(c.applied?'Applied':c.dismissed?'Dismissed':'Awaiting your decision',c.applied?'':'pending')}<p><strong>${esc(c.actor.name)}</strong> · ${esc(c.actor.model||'imported package')}<br>${c.data.components.length} components · ${c.data.properties.length} properties · ${c.data.findings.length} findings</p>${c.usage?`<p>${esc(c.usage.inputTokens??'?')} input / ${esc(c.usage.outputTokens??'?')} output tokens${c.usage.usd!=null?' · $'+Number(c.usage.usd).toFixed(4)+' ('+esc(c.usage.priceKind)+')':' · cost not reported'}</p>`:''}<div class="package-actions"><button type="button" class="button" data-action="contribution" data-id="${c.id}">Inspect proposal ↗</button>${!c.applied&&!c.dismissed?`<button type="button" class="button" data-action="apply-contribution" data-id="${c.id}">Apply proposal</button><button type="button" class="text-button" data-action="dismiss-contribution" data-id="${c.id}">Dismiss with reason</button>`:''}</div>${c.dismissed?`<p>${esc(c.dismissalRationale)}</p>`:''}</article>`).join('')||'<p class="source-note">No contribution has been requested or imported.</p>'}<div class="inline-actions"><button type="button" class="button" data-action="import-package">Import agent package ↗</button><button type="button" class="button" data-action="export-context">Export context & schema ↗</button></div><h3>Findings & disagreements (${d.findings.length})</h3>${renderFindingCards(d.findings)}<h3>Verification</h3><p class="dialog-copy">Executed commands, source judgments, and agent reports are recorded with their own provenance. A model can challenge source; it cannot certify runtime behavior from a diff.</p><div class="inline-actions"><button type="button" class="button" data-action="run-check">Run a local check ↗</button><button type="button" class="button" data-action="jev" ${!state.boot.jev?'disabled':''}>Ask Jev about source claims ↗</button></div>${!state.boot.jev?'<p class="source-note">Jev is optional. Connect it by setting TYPESAFE_API_KEY in the server environment.</p>':''}`);return;}
 if(m.kind==='contribution'){const c=d.contributions.find(c=>c.id===m.data.id);modalFrame(c.actor.name+' · '+c.actor.role,'UNAPPLIED PROPOSAL / RECORDED PACKAGE',`<p class="dialog-copy">${c.applied?'Applied to this review model.':c.dismissed?'Dismissed with rationale: '+esc(c.dismissalRationale):'Inspect before applying. Component proposals replace the current component model and reset component/property decisions; uncovered source files stay visible.'}</p><h3>Components</h3>${c.data.components.map(x=>`<article class="agent-package"><strong>${esc(x.title)}</strong><p>${esc(x.responsibility)}</p><p>${x.files.map(esc).join('<br>')}</p>${x.behavior.map(b=>`<div class="property-contract"><h3>${esc(b.label)}</h3><p>Before: ${esc(b.before)}<br>After: ${esc(b.after)}</p>${anchors(b.sources)}</div>`).join('')}</article>`).join('')||'<p class="source-note">Keeps the current component model.</p>'}<h3>Proposed connections</h3>${(c.data.relationships||[]).map(l=>`<div class="property-contract"><h3>${esc(l.from)} → ${esc(l.to)} · ${esc(l.kind)}</h3><p>${esc(l.reason)}</p>${anchors(l.sources)}</div>`).join('')||'<p class="source-note">No semantic connections proposed.</p>'}<h3>Property proposals</h3>${c.data.properties.map(p=>`<div class="property-contract"><h3>${esc(p.title)}</h3><p>When ${esc(p.condition)}, ${esc(p.expectation)}</p><p>Violation: ${esc(p.violation)}</p>${anchors(p.sources)}</div>`).join('')||'<p class="source-note">No new property definitions.</p>'}<h3>Findings</h3>${c.data.findings.map(f=>`<div class="finding-row"><h3>${esc(f.claim)}</h3><p>${esc(f.reasoning)}</p><p>Scope: ${esc(f.scope)}<br>Resolving check: ${esc(f.resolvingCheck)}</p>${anchors(f.sources)}</div>`).join('')||'<p class="source-note">No findings in this package.</p>'}${!c.applied&&!c.dismissed?`<div class="form-actions"><button type="button" class="button" data-action="dismiss-contribution" data-id="${c.id}">Dismiss with reason</button><button type="button" class="button primary" data-action="apply-contribution" data-id="${c.id}">Apply proposal</button></div>`:''}`);return;}
 if(m.kind==='dismiss'){modalFrame('Why set this proposal aside?','RETAIN THE DISAGREEMENT',`<form id="dismiss-form">${textarea('Reason','rationale','','required')}<div class="form-actions"><button class="button primary">Record dismissal</button></div></form>`);return;}
 if(m.kind==='import'){modalFrame('Bring your agent’s review.','REVISION-BOUND JSON PACKAGE',`<p class="dialog-copy">Export the context and schema for your coding agent, then import its JSON result. Packages must name the exact base/head commits. Imported test claims are labeled reported, even if they say “pass”.</p><form id="import-form"><div class="form-row">${field('Producer name','name','My agent')}<label class="field">Role<select name="role"><option value="reviewer">Reviewer</option><option value="author">Author / modeler</option><option value="verifier">Verifier</option></select></label></div><label class="field">Load JSON file<input type="file" id="package-file" accept=".json,application/json"></label>${textarea('Agent package JSON','package','','required spellcheck="false"')}<div class="form-actions"><button class="button primary">Validate & import proposal</button></div></form>`);return;}
 if(m.kind==='check'){modalFrame('Run a check on this candidate.','EXECUTED COMMAND EVIDENCE',`<p class="dialog-copy">Reviewed repository: ${esc(d.repository.path)}<br>Candidate: ${d.snapshot.head.commit}. Choose where the command runs. It uses your normal local environment; dependencies are not installed automatically.</p><form id="check-form"><label class="field">Execution folder<select name="execution"><option value="snapshot">Isolated copy of this reviewed commit (recommended)</option><option value="checkout" ${d.repository.bare?'disabled':''}>Current project checkout · must match candidate and be clean</option></select><small>Isolated copies are saved in the app’s data/checkouts folder. Your original branch is untouched.</small></label>${textarea('Command as a JSON argument list','argv',m.data.argv||'["node", "--test"]','required spellcheck="false"')}<p class="source-note">Examples: ["bun","test"] or ["npm","test","--","--run"]. No shell expansion is performed.</p><h3>Related properties (optional)</h3>${d.properties.map(p=>`<label class="check-label compact"><input type="checkbox" name="propertyIds" value="${p.id}">${esc(p.title)}</label>`).join('')||'<p class="source-note">A command can be recorded without behavioral properties.</p>'}<details><summary>How property-specific observations work</summary><p class="dialog-copy">An instrumented check can print this JSON line for an actual assertion. Select the corresponding property above. The viewer records the observation alongside raw output and the checkout fingerprint.</p><pre class="source-view">DOCVIZ_OBSERVATION {"propertyId":"your-id","result":"holds","assertion":"what the executed check asserted"}</pre><p class="source-note">Allowed results: holds, fails, unknown. A zero exit code without an explicit observation is command-level evidence only.</p></details><div class="form-actions"><button class="button primary">Run command & capture evidence</button></div></form>`);return;}
 if(m.kind==='review'){renderReview();return;}
 if(m.kind==='receipt'){renderReceipt();return;}
}
function renderJobs(){return state.jobs.filter(j=>j.reviewId===state.doc?.id||!j.reviewId).slice(-8).reverse().map(j=>`<div class="job-state ${j.status==='failed'?'failed':''}">${j.status==='running'?'<span class="busy-dot"></span>':''}<strong>${esc(j.label)} · ${esc(j.status)}</strong>${j.error?`<p>${esc(j.error)}</p>`:''}</div>`).join('');}
async function loadModalSource(){const m=state.modal,{path,side='diff'}=m.data,id=state.doc.id;try{const value=await api(`/api/reviews/${id}/${side==='diff'?'diff':'source'}?path=${encodeURIComponent(path)}${side==='diff'?'':'&side='+side}`);if(state.modal===m&&$('#modal-source')){$('#modal-source').innerHTML=sourceHTML(value,side,m.data.from?m.data:null);const pane=$('.source-view',$('#modal-source')),line=$('.focus-line',pane);if(line){const offset=line.getBoundingClientRect().top-pane.getBoundingClientRect().top+pane.scrollTop;pane.scrollTop=Math.max(0,offset-pane.clientHeight/2+line.clientHeight/2);}}}catch(error){if(state.modal===m&&$('#modal-source'))$('#modal-source').innerHTML=`<p class="dialog-copy">${esc(error.message)}</p>`;}}
function renderReview(){const d=state.doc;state.reviewDraft={...d.review,...state.reviewDraft};const r=state.reviewDraft;modalFrame('Review the change, here.','PRE-PR · HUMAN REVIEW',`<div class="review-callout"><strong>${esc(d.repository.name)} · candidate ${short(d.snapshot.head.commit)}</strong><p>Inspect each responsibility and property, resolve the findings, then record a review of this exact revision.</p>${badge(d.freshness.status==='current'?'Refs current':'Refs moved',d.freshness.status==='current'?'':'bad')} ${badge(d.evidence.filter(e=>e.kind==='executed-command').length+' executed commands','neutral')}</div><div class="review-list-title"><span>CHANGED COMPONENTS</span></div>${d.components.filter(c=>c.changedFiles.length).map(c=>`<div class="review-contract-row"><button type="button" data-action="review-component" data-component="${c.id}">${esc(c.title)} ↗<small>${c.changedFiles.length} changed files · ${esc(c.basis)}</small></button><select data-component-decision="${c.id}" aria-label="Review component ${esc(c.title)}">${decisionOptions(d.review.componentDecisions[c.id])}</select></div>`).join('')}<div class="review-list-title"><span>PROPERTY DECISIONS · ${Object.keys(d.review.propertyDecisions).length} / ${d.properties.length}</span><button type="button" class="text-button" data-action="add-property">Add property ↗</button></div>${d.properties.map(p=>{const[label]=propertyStatus(p);return `<div class="review-contract-row"><button type="button" class="review-property-open" data-action="property" data-property="${p.id}">${esc(p.title)} ↗<small>${esc(label)} · inspect behavior, evidence & agents</small></button><select data-property-decision="${p.id}" aria-label="Review property ${esc(p.title)}">${decisionOptions(d.review.propertyDecisions[p.id])}</select></div>`;}).join('')||'<p class="dialog-copy">No behavioral property is specified. You can record a source review with this limitation, or define properties before a behavioral review.</p>'}<div class="review-list-title"><span>AGENT FINDINGS · ${d.findings.length}</span><button type="button" class="text-button" data-action="agents">Contributions ↗</button></div>${renderFindingCards(d.findings)}<label class="field">Review scope<select data-review-field="scope"><option value="source" ${r.scope==='source'?'selected':''}>Source review · behavior may remain unverified</option><option value="behavior" ${r.scope==='behavior'?'selected':''}>Behavioral review · requires confirmed property definitions</option></select></label><label class="field">Local reviewer<input data-review-field="reviewer" value="${esc(r.reviewer)}" autocomplete="name"></label><label class="field">Review rationale & remaining follow-ups<textarea data-review-field="rationale" placeholder="What did you inspect? Why is this change acceptable within that scope? What remains unknown?">${esc(r.rationale)}</textarea></label><h3>Evidence limitations</h3><ul class="review-limitations">${d.acceptance.gaps.map(g=>`<li>${esc(g)}</li>`).join('')}</ul><label class="check-label"><input type="checkbox" data-review-field="acknowledgedGaps" ${r.acknowledgedGaps?'checked':''}><span>I reviewed these limits and accept the change within my stated scope.<small>This records my judgment; it does not turn missing evidence into proof.</small></span></label><div id="review-gate"></div><div id="review-save-state" class="review-save-state">Saved locally</div><div class="form-actions spread"><button type="button" class="text-button" data-action="close-dialog">Save & continue exploring</button><button type="button" class="button primary" id="finish-review" data-action="finish">Record review & prepare handoff →</button></div>`);updateReviewGate();}
function updateReviewGate(){const target=$('#review-gate');if(target&&state.doc){target.innerHTML=state.doc.acceptance.ready?'<p class="saved-review">Ready to record this revision.</p>':`<p class="source-note">Before recording:</p><ul class="review-limitations">${state.doc.acceptance.reasons.map(r=>`<li>${esc(r)}</li>`).join('')}</ul>`;$('#finish-review').disabled=!state.doc.acceptance.ready;if($('#review-save-state'))$('#review-save-state').textContent=Object.keys(pendingPatch).length?'Saving…':'Saved locally';}}
async function renderReceipt(){const d=state.doc;modalFrame('Review recorded. Ready for your PR.','REVISION-BOUND REVIEW RECEIPT',`<div class="review-callout"><strong>${esc(d.receipt?.reviewer)} · ${esc(d.receipt?.disposition)}</strong><p>${esc(d.receipt?.rationale)}</p>${badge(d.receiptCurrent?'Current receipt':'Historical receipt',d.receiptCurrent?'':'pending')}</div><div class="snapshot-ids"><div>REVIEWED CANDIDATE<code>${d.snapshot.head.commit}</code></div><div>RECEIPT<code>${d.receipt?.id}</code></div></div><p class="dialog-copy">Copy the handoff into your PR description. Integration CI still needs to run against the current target. The receipt stays local until you export or share it.</p><div class="inline-actions"><button type="button" class="button primary" data-action="copy-handoff">Copy PR handoff</button><button type="button" class="button" data-action="download-receipt">Download receipt JSON</button><button type="button" class="button" data-action="download-handoff">Download handoff Markdown</button></div><pre id="handoff-preview" class="source-view">Loading handoff…</pre>`);try{const result=await api('/api/reviews/'+d.id+'/export');state.handoff=result;if($('#handoff-preview'))$('#handoff-preview').textContent=result.markdown;}catch(e){if($('#handoff-preview'))$('#handoff-preview').textContent=e.message;}}
async function chooseProject(id){modal('project',{repositoryId:id,tab:'local',...(state.doc?.repository.id===id?{baseRef:state.doc.snapshot.base.ref,headRef:state.doc.snapshot.head.ref}:{})});if(id){const refs=await api('/api/repositories/'+id+'/refs');if(state.modal?.kind==='project'&&state.modal.data.repositoryId===id){state.modal.data.refs=refs;renderModal();}}}
function download(name,value,type='application/json'){const blob=new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function jobStarted(job){state.jobs.push(job);render();modal('agents');toast(job.label+' started.');}
async function perform(button){const a=button.dataset.action,id=button.dataset.id,pid=button.dataset.property;
 if(a==='retry-github'){await loadGitHubReview();return;}if(a==='verify-property'){state.verificationProperty=pid;state.level='verify';render();return;}if(a==='verify-evidence'){modal('property',{id:pid,tab:'evidence'},!!state.modal);return;}if(a==='verify-challenges'){modal('property',{id:pid,tab:'agents'},!!state.modal);return;}if(a==='verify-source'){state.mode='component';state.level='implementation';render();return;}if(a==='close-dialog'){closeModal();return;}if(a==='back-modal'){await backModal();return;}if(a==='home'){await flushReviewSave();state.doc=null;state.reviewDraft=null;history.replaceState(null,'',location.pathname);await bootstrap();render();return;}
 if(a==='open-project'||a==='add-project'){await chooseProject(button.dataset.repo||state.doc?.repository.id||state.boot.repositories[0]?.id);return;}if(a==='project-tab'){state.modal.data.tab=button.dataset.tab;renderModal();return;}if(a==='open-review'){await openReview(id);return;}
 if(a==='about'||a==='snapshot'){modal(a,{},!!state.modal);return;}if(a==='world'){state.mode='world';render();return;}if(a==='properties'){state.mode='component';state.level='properties';render();return;}if(a==='level'){state.level=button.dataset.level;render();return;}if(a==='lens'){state.lens=button.dataset.lens;drawGraph();$$('[data-action="lens"]').forEach(b=>b.classList.toggle('selected',b===button));return;}
 if(a==='select-component'){const cid=button.dataset.component,now=Date.now(),enter=lastNodeClick.id===cid&&now-lastNodeClick.at<600;lastNodeClick={id:cid,at:now};selectComponent(cid,enter);return;}if(a==='visit-connected'){closeModal();selectComponent(button.dataset.component,true);return;}if(a==='select-linked'){selectComponent(button.dataset.component,true);return;}if(a==='enter-component'||a==='enter'){state.mode='component';state.level='verify';render();return;}if(a==='inspector'){state.inspector=button.dataset.tab;render();return;}
 if(a==='describe-component'){modal('component',{},!!state.modal);return;}if(a==='review-component'){closeModal();selectComponent(button.dataset.component,true);state.level='implementation';render();return;}
 if(a==='property'){modal('property',{id:pid},!!state.modal);return;}if(a==='add-property'){modal('property-form',{},!!state.modal);return;}if(a==='edit-property'){modal('property-form',{id:pid},true);return;}if(a==='property-tab'){state.modal.data.tab=button.dataset.tab;renderModal();return;}if(a==='confirm-property'){await flushReviewSave();await action({action:'confirm-property',propertyId:pid});state.reviewDraft=null;renderModal();return;}
 if(a==='copy-property-id'){await navigator.clipboard.writeText(pid);toast('Property ID copied.');return;}if(a==='record-property'){await flushReviewSave();await patchReview({propertyDecisions:{[pid]:$('#property-decision').value}});state.reviewDraft=null;await backModal();return;}
 if(a==='file'||a==='anchor'){modal('source',{path:button.dataset.path,side:a==='file'?'diff':button.dataset.side,from:Number(button.dataset.from),to:Number(button.dataset.to)},!!state.modal);return;}if(a==='source-mode'){state.fileMode=button.dataset.mode;render();return;}if(a==='modal-source-mode'){state.modal.data.side=button.dataset.side;renderModal();return;}
 if(a==='finding'||a==='evidence'||a==='contribution'||a==='relationship'){modal(a,{id},!!state.modal);return;}if(a==='agents'){await flushReviewSave();modal('agents',{},!!state.modal);return;}if(a==='dismiss-contribution'){modal('dismiss',{id},true);return;}if(a==='apply-contribution'){await flushReviewSave();await action({action:'apply-contribution',contributionId:id});state.reviewDraft=null;modal('agents');toast('Proposal applied. Confirm definitions before behavioral review.');return;}
 if(a==='import-package'){modal('import',{},true);return;}if(a==='export-context'){download('docviz-agent-context-'+short(state.doc.snapshot.head.commit)+'.json',await api('/api/reviews/'+state.doc.id+'/context'));return;}
 if(a==='run-check'){modal('check',{},!!state.modal);return;}if(a==='jev'){await jobStarted(await action({action:'jev'}));return;}
 if(a==='review'){await flushReviewSave();state.reviewDraft=null;modal(state.doc.receiptCurrent?'receipt':'review');return;}
 if(a==='finish'){await flushReviewSave();await action({action:'finish'});await bootstrap();modal('receipt');return;}
 if(a==='refresh'){await flushReviewSave();setDoc(await action({action:'refresh'}));state.reviewDraft=null;state.sourceCache.clear();history.replaceState(null,'','#review='+state.doc.id);await bootstrap();render();toast('Opened the current comparison.');return;}
 if(a==='copy-handoff'){await navigator.clipboard.writeText(state.handoff.markdown);toast('PR handoff copied.');return;}if(a==='download-receipt'){download('docviz-review-'+short(state.doc.snapshot.head.commit)+'.json',state.handoff.receipt);return;}if(a==='download-handoff'){download('docviz-pr-handoff.md',state.handoff.markdown,'text/markdown');return;}
}
document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button||button.disabled)return;event.preventDefault();perform(button).catch(report);});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='component-search'){state.search=el.value;drawGraph();}if(el.dataset.reviewField){const key=el.dataset.reviewField,value=el.type==='checkbox'?el.checked:el.value;state.reviewDraft={...state.reviewDraft,[key]:value};scheduleReviewSave({[key]:value});}});
document.addEventListener('change',event=>{const el=event.target;(async()=>{if(el.id==='project-select'){await chooseProject(el.value);return;}if(el.id==='source-file'){state.file=el.value;loadMainSource();return;}if(el.id==='package-file'&&el.files[0]){$('[name="package"]').value=await el.files[0].text();return;}if(el.id==='property-decision'){state.modal.data.decision=el.value;return;}
 if(el.dataset.componentDecision||el.dataset.propertyDecision){await flushReviewSave();const field=el.dataset.componentDecision?'componentDecisions':'propertyDecisions',id=el.dataset.componentDecision||el.dataset.propertyDecision;await patchReview({[field]:{[id]:el.value}});state.reviewDraft=null;if(state.modal?.kind==='review')renderModal();}
 })().catch(report);});
document.addEventListener('submit',event=>{event.preventDefault();const form=event.target,values=Object.fromEntries(new FormData(form));const button=$('button[type="submit"],button:not([type])',form);if(button)button.disabled=true;(async()=>{
 if(form.id==='add-repository-form'){const repo=await api('/api/repositories',{path:values.path});await bootstrap();await chooseProject(repo.id);}
 if(form.id==='open-comparison-form'){const doc=await api('/api/open',{repositoryId:state.modal.data.repositoryId,...values});$('#dialog').close();state.modal=null;await bootstrap();await openReview(doc.id);}
 if(form.id==='open-pr-form'){const job=await api('/api/open-pr',{url:values.url});state.jobs.push(job);$('#dialog-content').innerHTML='<div class="job-state"><span class="busy-dot"></span>Loading the GitHub comparison. You can close this dialog while it loads.</div>';state.pendingPR=job.id;}
 if(form.id==='component-form'){await action({action:'component',componentId:state.selected,component:values});await backModal();}
 if(form.id==='property-form'){const propertyId=state.modal.data.id,property={...values,sources:JSON.parse(values.sources)};await flushReviewSave();await action({action:'property',property,propertyId});state.reviewDraft=null;await backModal();}
 if(form.id==='finding-form'){await flushReviewSave();await patchReview({findingResolutions:{[state.modal.data.id]:values}});state.reviewDraft=null;await backModal();}
 if(form.id==='dismiss-form'){await action({action:'dismiss-contribution',contributionId:state.modal.data.id,rationale:values.rationale});state.reviewDraft=null;modal('agents');}
 if(form.id==='agent-form'){await jobStarted(await action({action:'generate',...values}));}
 if(form.id==='import-form'){await action({action:'import',name:values.name,role:values.role,package:JSON.parse(values.package)});state.reviewDraft=null;modal('agents');toast('Package validated. Inspect it before applying.');}
 if(form.id==='check-form'){await jobStarted(await action({action:'check',argv:JSON.parse(values.argv),propertyIds:new FormData(form).getAll('propertyIds'),execution:values.execution}));}
 })().catch(report).finally(()=>{if(button&&button.isConnected)button.disabled=false;});});
$('#dialog').addEventListener('cancel',event=>{event.preventDefault();closeModal();});
let polling=false;
async function poll(){if(polling||!state.boot)return;polling=true;try{const active=state.jobs.filter(j=>j.status==='running');let changed=false;for(const job of active){const fresh=await api('/api/jobs/'+job.id);Object.assign(job,fresh);if(fresh.status!=='running'){changed=true;toast(fresh.status==='completed'?fresh.label+' completed. Inspect its recorded result.':fresh.error);if(job.id===state.pendingPR&&fresh.status==='completed'){state.pendingPR=null;$('#dialog').close();state.modal=null;await bootstrap();await openReview(fresh.reviewId);}}}if(changed){await bootstrap();if(state.doc){await flushReviewSave();setDoc(await api('/api/reviews/'+state.doc.id));state.reviewDraft=null;render();if(state.modal&&['agents','review','property'].includes(state.modal.kind))renderModal();}}else if($('#agent-job-list'))$('#agent-job-list').innerHTML=renderJobs();}catch(error){report(error);}finally{polling=false;}}
window.addEventListener('focus',()=>{if(state.doc&&!state.modal)api('/api/reviews/'+state.doc.id).then(d=>{setDoc(d);render();}).catch(report);});
window.addEventListener('resize',()=>{if(state.doc&&state.mode==='world')drawGraph();});
try{await bootstrap();if(githubContext){document.body.classList.add('github-surface');await loadGitHubReview();}else{const initial=location.hash.match(/^#review=([a-f0-9]+)$/);if(initial)await openReview(initial[1]).catch(error=>{report(error);renderHome();});else renderHome();}}catch(error){showGitHubError(error);}setInterval(poll,2000);
document.addEventListener('focusout',event=>{if(event.target.dataset?.reviewField)flushReviewSave().catch(report);});
window.addEventListener('pagehide',()=>{flushReviewSave().catch(()=>{});});
function evidenceMap(p){const es=evidenceFor(p),observations=es.flatMap(e=>e.stale||e.outdatedPropertyIds?.includes(p.id)?[]:(e.observations||[]).filter(o=>o.propertyId===p.id));return `<div class="evidence-map" aria-label="Property evidence path"><button type="button" data-action="property-tab" data-tab="behavior"><strong>${p.sources.length}</strong><span>Source links</span><small>inspect code</small></button><span aria-hidden="true">→</span><button type="button" data-action="property-tab" data-tab="evidence"><strong>${es.filter(e=>e.kind==='reported'||e.kind==='source-judgment').length}</strong><span>Reports / judgments</span><small>claimed support</small></button><span aria-hidden="true">→</span><button type="button" data-action="property-tab" data-tab="evidence" class="${observations.some(o=>o.result==='fails')?'failure':''}"><strong>${observations.length||'?'}</strong><span>Executed assertions</span><small>${observations.length?observations.map(o=>o.result).join(', '):'runtime unknown'}</small></button></div>`;}
function propertyBehavior(p){const c=state.doc.components.find(c=>c.id===p.componentId);return c?.behavior.length?`<details class="behavior-context"><summary>Explore the component’s before / after explanation</summary><p class="source-note">Source-grounded explanation from the model; not an observed execution trace.</p>${c.behavior.map(b=>`<article class="agent-package"><strong>${esc(b.label)}</strong><div class="behavior-compare"><div><small>BASE</small><p>${esc(b.before)}</p></div><span aria-hidden="true">→</span><div><small>CANDIDATE</small><p>${esc(b.after)}</p></div></div>${anchors(b.sources)}</article>`).join('')}</details>`:'';}
function verificationOverview(){const v=verificationSummary(state.doc);return `<div class="verification-overview" aria-label="Visual verification coverage"><button type="button" data-action="world"><strong>${v.changedComponents}</strong><span>changed components</span></button><button type="button" data-action="properties"><strong>${v.mappedObservations} / ${v.properties}</strong><span>properties with mapped observations</span></button><button type="button" data-action="agents"><strong>${v.openFindings}</strong><span>open agent claims</span></button><button type="button" data-action="review"><strong>${state.doc.receiptCurrent?'Recorded':'Open'}</strong><span>your review decision</span></button></div>`;}
function renderVerification(c){const v=verificationFor(state.doc,c.id,state.verificationProperty),p=v.selected,decision={satisfied:'Satisfied within reviewed scope','follow-up':'Retained as a follow-up',changes:'Changes required'}[v.decision]||'Not reviewed';
 if(!p)return `<div class="verification-intro"><span class="eyebrow">VISUAL VERIFICATION</span><h2>Give this component something to verify.</h2><p>Its ${c.changedFiles.length} changed files are real. No behavioral property has been supplied yet, so evidence cannot establish a property here.</p></div><div class="verify-path"><button type="button" data-action="verify-source"><span>01 · CHANGE</span><strong>${c.changedFiles.length} changed files</strong><small>Inspect the actual diff</small></button><div class="verify-empty-stage"><span>02 · PROPERTY</span><strong>No definition yet</strong><small>Name the condition and expected result</small></div><div class="verify-empty-stage"><span>03 · EVIDENCE</span><strong>Awaiting a property</strong><small>Nothing is treated as verified</small></div></div><div class="inline-actions"><button type="button" class="button primary" data-action="add-property">Define a property</button><button type="button" class="button" data-action="agents">Ask an agent to draft the model</button></div>`;
 return `<div class="verification-intro"><span class="eyebrow">VISUAL VERIFICATION · EXACT CANDIDATE ${short(state.doc.snapshot.head.commit)}</span><h2>Follow a claim to its evidence.</h2><p>Select a property below. Inspect what is expected, what was actually checked, and what an agent challenges before recording your decision.</p></div><div class="verify-properties" role="group" aria-label="Properties to verify">${v.properties.map(x=>`<button type="button" class="verify-property-bubble ${x.id===p.id?'selected':''}" aria-pressed="${x.id===p.id}" data-action="verify-property" data-property="${x.id}"><span>${esc(x.id)}</span><strong>${esc(x.title)}</strong></button>`).join('')}</div><div class="verify-path" aria-label="Change to evidence and decision"><button type="button" data-action="verify-source"><span>01 · CHANGE</span><strong>${c.changedFiles.length} source edits</strong><small>Open pinned implementation</small></button><button type="button" data-action="property" data-property="${p.id}"><span>02 · PROPERTY</span><strong>${esc(p.title)}</strong><small>${p.authority==='human-confirmed'?'Definition confirmed':'Definition proposed'}</small></button><button type="button" data-action="verify-evidence" data-property="${p.id}"><span>03 · EVIDENCE</span><strong>${v.observations.length} mapped observations</strong><small>${v.evidence.length} linked artifacts · inspect scope</small></button><button type="button" data-action="property" data-property="${p.id}"><span>04 · YOUR DECISION</span><strong>${decision}</strong><small>Evidence and judgment stay separate</small></button></div><article class="verify-contract"><div><span class="view-label">WHEN</span><p>${esc(p.condition)}</p></div><div><span class="view-label">EXPECTED RESULT</span><p>${esc(p.expectation)}</p></div><div><span class="view-label">VIOLATION</span><p>${esc(p.violation)}</p></div><button type="button" class="text-button" data-action="property" data-property="${p.id}">Inspect or edit this contract →</button></article><div class="verify-observation ${v.observation.kind}"><strong>${esc(v.observation.title)}</strong><p>${esc(v.observation.detail)}</p></div><div class="verify-branches"><section><div class="verify-section-heading"><h3>Evidence connected to this property</h3><span>${v.evidence.length}</span></div>${v.evidence.map(e=>`<button type="button" class="verify-artifact ${!e.applicable?'historical':''}" data-action="evidence" data-id="${e.id}"><span class="view-label">${esc(e.kind==='executed-command'?'EXECUTED COMMAND':e.kind==='reported'?'PRODUCER REPORT':'SOURCE JUDGMENT')}</span><strong>${esc(e.kind==='executed-command'?e.argv?.join(' ')||'Recorded command':e.actor?.name||e.kind)}</strong><p>${esc(e.result)}${!e.applicable?' · historical for this definition':''}</p><small>${esc(e.scope)}</small><span class="verify-open">Inspect raw evidence →</span></button>`).join('')||'<div class="verify-absence">No evidence artifact is linked to this property. Source links remain available below.</div>'}<button type="button" class="button small" data-action="run-check">Run a check</button></section><section><div class="verify-section-heading"><h3>Agent challenges to this property</h3><span>${v.propertyFindings.length}</span></div>${v.propertyFindings.map(f=>`<button type="button" class="verify-claim" data-action="finding" data-id="${f.id}"><span class="view-label">${esc(f.actor?.name||'Producer')} · ${esc(f.actor?.role||'review')}</span><strong>${esc(f.claim)}</strong><small>${esc(f.resolvingCheck)}</small><span class="verify-open">${state.doc.review.findingResolutions[f.id]?'Inspect your disposition':'Inspect reasoning & distinguishing check'} →</span></button>`).join('')||'<div class="verify-absence">No agent challenge is recorded for this property. Absence of a challenge does not establish correctness.</div>'}${v.contextFindings.length?`<details class="behavior-context"><summary>${v.contextFindings.length} additional claims about this component</summary>${renderFindingCards(v.contextFindings)}</details>`:''}<p class="source-note">Claims retain their individual authors. Similar claims are not automatically counted as consensus, and no disagreement is invented.</p></section></div>${propertyBehavior(p)}<details class="behavior-context"><summary>Inspect ${p.sources.length} exact source anchors</summary>${anchors(p.sources)}</details>`;
}
function showGitHubError(error){$('#app').innerHTML=`<section class="github-connection"><span class="eyebrow">DOCVIZ · GITHUB VISUAL REVIEW</span><h1>The visual review could not open.</h1><p>${esc(error.message)}</p><p>Keep the local engine running. Private PR metadata needs valid GitHub credentials in that engine; a browser login alone is not an API credential.</p><button type="button" class="button primary" data-action="retry-github">Retry connection</button><a class="button" href="http://127.0.0.1:47836/" target="_blank" rel="noopener">Open local engine</a></section>`;}
async function loadGitHubReview(){
 $('#app').innerHTML='<section class="github-connection"><span class="eyebrow">DOCVIZ · GITHUB VISUAL REVIEW</span><h1>Opening this change’s component world…</h1><p>Resolving the real base and candidate commits. No model analysis or project command runs merely by opening this view.</p></section>';
 try{const job=await api(githubContext.kind==='comparison'?'/api/open-github-comparison':'/api/open-pr',{url:githubContext.url});let current=job;for(let i=0;i<180&&current.status==='running';i++){await new Promise(r=>setTimeout(r,700));current=await api('/api/jobs/'+job.id);}if(current.status!=='completed')throw new Error(current.error||'The PR is still loading. Retry in a moment.');await bootstrap();await openReview(current.reviewId);document.title='Docviz visual review · '+state.doc.repository.name;}catch(error){showGitHubError(error);}
}

function sourceOnGitHub(value,mode,focus){const contextURL=state.doc?.pr?.url||state.doc?.githubComparison?.url;if(!contextURL)return null;const match=contextURL.match(/^(https:\/\/github\.com\/[^/]+\/[^/]+)\/(?:pull\/\d+|compare\/.+)$/);if(!match)return null;if(mode==='diff')return match[1]+'/compare/'+state.doc.snapshot.base.commit+'...'+state.doc.snapshot.head.commit;const path=value.path.split('/').map(encodeURIComponent).join('/');return match[1]+'/blob/'+value.commit+'/'+path+(focus?.from?'#L'+focus.from+(focus.to>focus.from?'-L'+focus.to:''):'');}
